mockup.css:
.mock-section-sticky-pair { background: #f5f3ec; color: #191712; font-family: var(--f-sans);
  display: grid; grid-template-columns: 33% 1fr; gap: 5cqw; padding: 0 6cqw; }
.mock-section-sticky-pair .pin { align-self: center; display: flex; flex-direction: column; gap: 1.6cqw; }
.mock-section-sticky-pair .pin em { font-style: normal; font-family: var(--f-mono); font-size: 1.15cqw;
  letter-spacing: .18em; text-transform: uppercase; opacity: .45; }
.mock-section-sticky-pair .pin h4 { margin: 0; font-family: var(--f-serif); font-size: 5cqw;
  line-height: 1.02; letter-spacing: -.02em; }
.mock-section-sticky-pair .pin p { margin: 0; font-size: 1.45cqw; line-height: 1.5; opacity: .7; max-width: 28ch; }
.mock-section-sticky-pair .scroll { display: flex; flex-direction: column; margin-block: -3.2cqw; }
.mock-section-sticky-pair .scroll .row { border-top: 1px solid rgba(25,23,18,.18);
  padding: 2cqw 0; display: grid; grid-template-columns: 1fr auto; gap: 2cqw; align-items: baseline; }
.mock-section-sticky-pair .scroll b { font-weight: 600; font-size: 1.95cqw; }
.mock-section-sticky-pair .scroll span { font-family: var(--f-mono); font-size: 1.2cqw; opacity: .45; }
.mock-section-sticky-pair .scroll .row p { grid-column: 1 / -1; margin: .5cqw 0 0; font-size: 1.35cqw;
  line-height: 1.45; opacity: .6; }
